-- Copiado em 22/11/2026 do registro de migrações do banco real (versão 20261121174024, aplicada em 21/11/2026).
-- Atenção: a f_03 (20261122070132) reescreveu esta função depois e tirou as etiquetas da cópia de segurança.
-- A correção é a 20261122080619_produto_etiquetas_no_exportar_depois_da_f03.sql.

CREATE OR REPLACE FUNCTION produto.exportar_familia(familia uuid) RETURNS json LANGUAGE plpgsql STABLE SET search_path TO '' AS $function$ declare f uuid := exportar_familia.familia; begin if produto.meu_papel(f) is distinct from 'casal' then raise exception 'so o casal baixa os dados da familia' using errcode = '42501'; end if; return json_build_object( 'exportado_em', now(), 'formato', 'Central da Familia v1', 'familia', (select to_json(x) from produto.familias x where x.id = f), 'membros', (select coalesce(json_agg(x order by x.criado_em), '[]') from produto.membros x where x.familia_id = f), 'envelopes', (select coalesce(json_agg(x order by x.criado_em), '[]') from produto.envelopes x where x.familia_id = f), 'limites_mes', (select coalesce(json_agg(x order by x.mes), '[]') from produto.limites_mes x where x.familia_id = f), 'cartoes', (select coalesce(json_agg(x order by x.criado_em), '[]') from produto.cartoes x where x.familia_id = f), 'lancamentos', (select coalesce(json_agg(x order by x.data, x.criado_em), '[]') from produto.lancamentos x where x.familia_id = f), 'etiquetas', (select coalesce(json_agg(x order by x.criado_em), '[]') from produto.etiquetas x where x.familia_id = f), 'lancamento_etiquetas', (select coalesce(json_agg(x order by x.criado_em), '[]') from produto.lancamento_etiquetas x where x.familia_id = f), 'config', (select coalesce(json_agg(x), '[]') from produto.config_familia x where x.familia_id = f), 'eventos', (select coalesce(json_agg(json_build_object('tipo', x.tipo, 'segundos', x.segundos, 'criado_em', x.criado_em) order by x.criado_em), '[]') from produto.eventos x where x.familia_id = f), 'codigos_equipe', (select coalesce(json_agg(json_build_object('membro_id', x.membro_id, 'expira_em', x.expira_em, 'usado_em', x.usado_em)), '[]') from produto.acesso_equipe x where x.familia_id = f), 'guardado_aplicacoes', (select coalesce(json_agg(x order by x.criado_em), '[]') from produto.pat_aplicacoes x where x.familia_id = f), 'guardado_movimentos', (select coalesce(json_agg(x order by x.data, x.criado_em), '[]') from produto.pat_movimentos x where x.familia_id = f), 'lembretes', (select coalesce(json_agg(x order by x.quando), '[]') from produto.esc_lembretes x where x.familia_id = f), 'diario_do_escritorio', (select coalesce(json_agg(x order by x.quando), '[]') from produto.esc_diario x where x.familia_id = f), 'cartao_custos', (select coalesce(json_agg(x), '[]') from produto.cartao_custos x where x.familia_id = f), 'cartao_faturas', (select coalesce(json_agg(x order by x.mes), '[]') from produto.cartao_faturas x where x.familia_id = f), 'feiras', (select coalesce(json_agg(x order by x.data), '[]') from produto.feiras x where x.familia_id = f), 'estoque_itens', (select coalesce(json_agg(x order by x.nome), '[]') from produto.estoque_itens x where x.familia_id = f), 'estoque_contagens', (select coalesce(json_agg(x order by x.data), '[]') from produto.estoque_contagens x where x.familia_id = f), 'uso_da_ia', (select coalesce(json_agg(json_build_object('funcao', x.funcao, 'custo_brl', x.custo_brl, 'criado_em', x.criado_em) order by x.criado_em), '[]') from produto.ia_chamadas x where x.familia_id = f)); end $function$;
